```python
from datetime import date, datetime, timedelta

SOWING_OFFSET_DAYS = 7 + 7  # 마지막 서리 후 14일


def sowing_date(last_frost):
    """마지막 서리 날짜로부터 14일 뒤의 파종 권장일을 ISO 날짜 문자열로 반환합니다.

    last_frost: 'YYYY-MM-DD' 형식의 문자열, date 객체 또는 datetime 객체
    날짜 형식이 아니면 ValueError를 발생시킵니다.
    """
    if isinstance(last_frost, datetime):
        base = last_frost.date()
    elif isinstance(last_frost, date):
        base = last_frost
    elif isinstance(last_frost, str):
        try:
            base = date.fromisoformat(last_frost.strip())
        except ValueError:
            raise ValueError(
                f"날짜 형식이 올바르지 않습니다 (YYYY-MM-DD 필요): {last_frost!r}"
            ) from None
    else:
        raise ValueError(
            f"날짜 형식이 아닙니다: {type(last_frost).__name__}"
        )

    return (base + timedelta(days=SOWING_OFFSET_DAYS)).isoformat()
```

```python
import math


def voltage_range(voltages):
    """배터리 전압 목록에서 유효한 숫자만 골라 (최솟값, 최댓값)을 반환한다.

    - None, 숫자로 변환할 수 없는 문자열, NaN/무한대 값은 제외한다.
    - bool은 숫자로 취급하지 않고 제외한다.
    - 숫자 형태의 문자열(예: "12.5")은 float로 변환해 포함한다.
    - 유효한 값이 하나도 없으면 None을 반환한다.
    """
    if voltages is None:
        return None

    valid = []
    for v in voltages:
        if v is None or isinstance(v, bool):
            continue
        try:
            num = float(v)
        except (TypeError, ValueError):
            continue
        if math.isnan(num) or math.isinf(num):
            continue
        valid.append(num)

    if not valid:
        return None
    return (min(valid), max(valid))
```

```javascript
function validateObservation(record) {
  // 24 * 60 = 1440

  // 객체가 없으면 검증 실패
  if (record === null || typeof record !== "object") {
    return false;
  }

  // species가 문자열이 아니거나 빈 문자열이면 false
  if (typeof record.species !== "string" || record.species === "") {
    return false;
  }

  // 관찰 시간이 문자열이 아니면 false
  var time = record.time;
  if (typeof time !== "string") {
    return false;
  }

  // HH:MM 형식은 정확히 5글자이고 가운데가 ":" 이어야 함
  if (time.length !== 5 || time.charAt(2) !== ":") {
    return false;
  }

  var hourText = time.substring(0, 2);
  var minuteText = time.substring(3, 5);

  // 시와 분의 각 글자가 숫자인지 검사
  var digits = "0123456789";
  var allText = hourText + minuteText;
  for (var i = 0; i < allText.length; i++) {
    if (digits.indexOf(allText.charAt(i)) === -1) {
      return false;
    }
  }

  var hour = Number(hourText);
  var minute = Number(minuteText);

  // 시는 0~23, 분은 0~59 범위여야 함
  if (hour < 0 || hour > 23) {
    return false;
  }
  if (minute < 0 || minute > 59) {
    return false;
  }

  return true;
}
```

관찰 시간 필드 이름은 `time`이라고 가정했습니다. 다른 이름을 쓰신다면 `record.time` 부분만 바꾸면 됩니다.

